    "practice_questions": "[{\"id\":\"pq_gen_pol_1\",\"question\":\"Which writ is issued by the Supreme Court to secure the release of an unlawfully detained person?\",\"options\":[\"Mandamus\",\"Habeas Corpus\",\"Quo-Warranto\",\"Certiorari\"],\"correct_index\":1,\"explanation\":\"Habeas Corpus is issued against unlawful detention.\"}]",
