    "practice_questions": "[{\"id\":\"pq_gen_econ_1\",\"question\":\"The difference between total government expenditure and total revenue receipts plus non-debt capital receipts is:\",\"options\":[\"Revenue Deficit\",\"Fiscal Deficit\",\"Primary Deficit\",\"Trade Deficit\"],\"correct_index\":1,\"explanation\":\"Fiscal Deficit represents the total borrowing requirements of the government.\"}]",
    "source_authority": "Indian Economy by Ramesh Singh (McGraw Hill 16th Edition)"
